-- Gravity Fight: часть 2 из 2 (версия 512710).
-- Части можно выполнять в любом порядке. Игра обновится, только когда выполнены ВСЕ 2 части этой версии;
-- до этого в игре остаётся прежний файл. Последняя строка результата скажет «готово» или сколько частей не хватает.
-- Буфер загрузки: части складываются сюда, в игру файл попадает только целиком.
create table if not exists public.game_upload (
  game_id text not null, part int not null, total int not null, body text not null,
  primary key (game_id, part)
);
alter table public.game_upload add column if not exists ver text not null default '';
alter table public.game_upload enable row level security;
revoke all on public.game_upload from anon, authenticated;
-- части других версий этой игры убираем, чтобы старое и новое не смешалось
delete from public.game_upload where game_id = 'gravity' and ver <> '512710';
insert into public.game_upload (game_id, part, total, ver, body) values ('gravity', 2, 2, '512710', $cpx$</script>
<script>(async()=>{try{if(!window.DecompressionStream)throw 0;const b=Uint8Array.from(atob(document.getElementById("gdz").textContent),c=>c.charCodeAt(0));const t=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("deflate-raw"))).text();const e=document.createElement("script");e.textContent=t;document.body.appendChild(e);try{document.getElementById("bplay").click()}catch(_){}/* сразу игра, без главного меню: меню — в паузе (⏸ → «Главное меню») */}catch(x){document.body.insertAdjacentHTML("beforeend","<div style=\"position:fixed;inset:0;display:grid;place-items:center;background:#111;color:#fff;font:16px sans-serif;padding:20px;text-align:center;z-index:99\">Браузер слишком старый для игры. Обновите Chrome, Safari или Firefox.</div>")}})();</script>
</body>
</html>
$cpx$)
on conflict (game_id, part) do update set total = excluded.total, ver = excluded.ver, body = excluded.body;

-- все части этой версии на месте и длина сходится → записать файл в игру и очистить буфер
update public.games g set file_html = s.html, updated_at = now()
  from (select string_agg(body, '' order by part) as html, count(*) as n from public.game_upload where game_id = 'gravity' and ver = '512710') s
 where g.id = 'gravity' and s.n = 2 and char_length(s.html) = 512710;
delete from public.game_upload where game_id = 'gravity' and (select char_length(file_html) from public.games where id = 'gravity') = 512710;

select case when (select char_length(file_html) from public.games where id = 'gravity') = 512710 then 'ГОТОВО: Gravity Fight обновлена'
  else 'НЕ ГОТОВО: загружено частей ' || (select count(*) from public.game_upload where game_id = 'gravity' and ver = '512710') || ' из 2, выполните остальные' end as status;
